import {writeFileSync} from 'node:fs';import {join,resolve} from 'node:path';import {spawn} from 'node:child_process';import {pathToFileURL} from 'node:url';
/** Stop the real Store.put exactly before/after COMMIT, after spilling with a small SQLite cache. */
export async function crashParsedPut(dir:string,paths:{store:string;job:string;archive:string},stage:'before'|'after',moduleRoot?:string){
 const module=(name:string)=>JSON.stringify(pathToFileURL(resolve(moduleRoot??'src',name+(moduleRoot?'.js':'.ts'))).href),script=join(dir,'parsed-put-worker.mjs');writeFileSync(script,`import{writeSync}from'node:fs';import{ParsedFinancialStore}from ${module('db/parsed-financial-store')};import{ParsedFinancialJob}from ${module('db/parsed-financial-job')};import{ObservedFinancialArchive}from ${module('db/observed-financial-archive')};import{createAutomaticFinancialSnapshots}from ${module('automatic-financial-snapshots')};const store=new ParsedFinancialStore(${JSON.stringify(paths.store)}),job=new ParsedFinancialJob(${JSON.stringify(paths.job)},{readOnly:true}),archive=new ObservedFinancialArchive(${JSON.stringify(paths.archive)},{readOnly:true}),plan=job.plan('cycle'),task=plan.tasks.find(t=>!store.get(t.extractionId)),source=archive.readSource({docID:task.identity.docID,sourceSha256:task.identity.sourceSha256,availableAt:task.availableAt}),result=createAutomaticFinancialSnapshots(source.xml,{docID:task.identity.docID,detailMetricIds:task.identity.detailMetricIds});job.close();archive.close();store.db.exec('PRAGMA cache_size=4');const original=store.db.exec.bind(store.db);store.db.exec=sql=>{if(sql==='COMMIT'){${stage==='after'?'original(sql);':''}writeSync(1,'READY\\n');Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0)}return original(sql)};store.put({identity:task.identity,parsedAt:'2026-10-31T00:00:00.000Z',outcome:{status:'completed',result}});throw Error('Store COMMIT was not intercepted');`);
 const child=spawn(process.execPath,['--import',resolve('node_modules/tsx/dist/loader.mjs'),script],{stdio:['ignore','pipe','pipe']}),closed=new Promise<void>(r=>child.once('close',()=>r()));
 try{await new Promise<void>((done,reject)=>{let output='',errors='';const timer=setTimeout(()=>reject(Error('Parsed put crash timeout')),20000);child.stdout.on('data',b=>{output+=b;if(output.includes('READY')){clearTimeout(timer);done()}});child.stderr.on('data',b=>errors=(errors+b).slice(-2000));child.once('error',e=>{clearTimeout(timer);reject(e)});child.once('exit',code=>{clearTimeout(timer);reject(Error('Early parsed put exit '+code+': '+errors))})})}finally{if(child.exitCode===null&&child.signalCode===null)child.kill('SIGKILL');await closed}
}
